CREATE OR REPLACE TEMP TABLE r AS
SELECT CAST(edge_id AS VARCHAR) AS edge_id, edge_id AS eid, any_value(source) AS s, any_value(target) AS t,
       CAST(first(osm_id ORDER BY mode IS NULL, mode, pmode) AS VARCHAR) AS osm_id, first(highway ORDER BY mode IS NULL, mode, pmode) AS highway, COALESCE(first(name ORDER BY mode IS NULL, mode, pmode), '') AS name,
       first(bridge ORDER BY mode IS NULL, mode, pmode) AS bridge, first(tunnel ORDER BY mode IS NULL, mode, pmode) AS tunnel, first(layer ORDER BY mode IS NULL, mode, pmode) AS layer, bool_or(oneway) AS oneway,
       any_value(walk_type) AS walk_type,
       first(junction ORDER BY mode IS NULL, mode, pmode) AS junction, first(edge_ref ORDER BY mode IS NULL, mode, pmode) AS edge_ref, first(lanes ORDER BY mode IS NULL, mode, pmode) AS lanes,
       COALESCE(bool_or(mode = 'driving'), false) AS driving, COALESCE(bool_or(mode = 'walking'), false) AS walking, COALESCE(bool_or(mode = 'cycling'), false) AS cycling,
       max(CASE WHEN pmode = 'driving' THEN access END) AS access_driving, max(CASE WHEN pmode = 'walking' THEN access END) AS access_walking, max(CASE WHEN pmode = 'cycling' THEN access END) AS access_cycling,
       first(geometry ORDER BY mode IS NULL, mode, pmode) AS geom
FROM (SELECT edge_id, source, target, osm_id, highway, name, bridge, tunnel, layer, oneway, geometry, NULL AS walk_type, junction AS junction, edge_ref AS edge_ref, lanes AS lanes, 'driving' AS mode, NULL AS pmode, NULL AS access FROM driving.edges UNION ALL SELECT edge_id, source, target, osm_id, highway, name, bridge, tunnel, layer, oneway, geometry, walk_type AS walk_type, junction AS junction, edge_ref AS edge_ref, lanes AS lanes, 'walking' AS mode, NULL AS pmode, NULL AS access FROM walking.edges UNION ALL SELECT edge_id, source, target, osm_id, highway, name, bridge, tunnel, layer, oneway, geometry, NULL AS walk_type, junction AS junction, edge_ref AS edge_ref, lanes AS lanes, 'cycling' AS mode, NULL AS pmode, NULL AS access FROM cycling.edges UNION ALL SELECT edge_id, source, target, osm_id, highway, name, bridge, tunnel, layer, oneway, geometry, NULL AS walk_type, junction AS junction, edge_ref AS edge_ref, lanes AS lanes, NULL AS mode, 'cycling' AS pmode, access FROM cycling.private_edges UNION ALL SELECT edge_id, source, target, osm_id, highway, name, bridge, tunnel, layer, oneway, geometry, NULL AS walk_type, junction AS junction, edge_ref AS edge_ref, lanes AS lanes, NULL AS mode, 'driving' AS pmode, access FROM driving.private_edges UNION ALL SELECT edge_id, source, target, osm_id, highway, name, bridge, tunnel, layer, oneway, geometry, NULL AS walk_type, junction AS junction, edge_ref AS edge_ref, lanes AS lanes, NULL AS mode, 'walking' AS pmode, access FROM walking.private_edges) GROUP BY edge_id;

COPY (SELECT r.* EXCLUDE (eid, s, t, geom), ST_AsWKB(r.geom) AS geometry FROM r ORDER BY r.eid) TO 'roads.parquet' (FORMAT parquet);
